import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];
  const timelines = [];
  const primitiveResults = [];
  let disposed = false;

  const makeMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makePlane = (width, height, material, z = 0) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);

    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    root.add(mesh);
    return mesh;
  };

  const paper = '#e8ecf2';
  const ink = '#16161d';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const panelMaterial = makeMaterial({
    transparent: true,
    opacity: 0.98
  });
  const panelUv = uv();
  panelMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, panelUv.y)
  );
  makePlane(3.2, 1.9, panelMaterial, -0.045);

  const shadowMaterial = makeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.55
  });
  makePlane(3.35, 2.02, shadowMaterial, -0.075);

  const imageMaterial = makeMaterial({
    color: paper,
    transparent: true,
    opacity: 1
  });
  const imagePlane = makePlane(2.9, 1.55, imageMaterial, 0.005);

  const edgeMaterials = [];
  const edgeSpecs = [
    [3.2, 0.035, 0, 0.935],
    [3.2, 0.035, 0, -0.935],
    [0.035, 1.9, -1.5825, 0],
    [0.035, 1.9, 1.5825, 0]
  ];

  for (const [width, height, x, y] of edgeSpecs) {
    const material = makeMaterial({
      color: accent,
      transparent: true,
      opacity: 0.22
    });
    edgeMaterials.push(material);

    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);

    const edge = new Mesh(geometry, material);
    edge.position.set(x, y, 0.04);
    root.add(edge);
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const content = typeof item?.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 3 : 0
    });

    textObject.position.set(-1.28, -0.7, 0.07);
    root.add(textObject);
    textObjects.push(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      loadedTextures.push(texture);
      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const playHover = (active) => {
    if (disposed) return;

    const timeline = gsap.timeline({
      defaults: { overwrite: 'auto' }
    });

    timeline.to(root.position, {
      y: active ? 0.15 : 0,
      duration: 0.45,
      ease: 'power3.out'
    });

    timeline.to(edgeMaterials, {
      opacity: active ? 0.58 : 0.22,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);

    timelines.push(timeline);
  };

  const press = () => {
    if (disposed) return;

    const timeline = gsap.timeline({
      defaults: { overwrite: 'auto' }
    });

    timeline
      .to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.42,
        ease: 'back.out(2)'
      });

    timelines.push(timeline);
    ctx.emit('hub-journal.select', { text: items[0]?.text ?? 'Journal 3' });
  };

  root.userData.handlers = {
    hover: (value) => {
      const active = typeof value === 'boolean'
        ? value
        : value?.active !== false;
      playHover(active);
    },
    focus: () => {
      if (disposed) return;
      const timeline = gsap.timeline({ defaults: { overwrite: 'auto' } });
      timeline.to(edgeMaterials, {
        opacity: 0.9,
        duration: 0.25,
        ease: 'power2.out'
      });
      timelines.push(timeline);
    },
    blur: () => {
      if (disposed) return;
      const timeline = gsap.timeline({ defaults: { overwrite: 'auto' } });
      timeline.to(edgeMaterials, {
        opacity: 0.22,
        duration: 0.3,
        ease: 'power2.out'
      });
      timelines.push(timeline);
    },
    click: press
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const primitiveFn = ctx.primitives?.[primitive.name];
    if (typeof primitiveFn === 'function') {
      const result = primitiveFn(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const result of primitiveResults) {
      result.cleanup?.();
      result.timeline?.kill?.();
    }

    for (const texture of loadedTextures) {
      texture.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }
  };

  return root;
}
